package com.jnapanam.sportszone.booking.model;
import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="bookings")public class Booking{
 @Id private UUID id;@Column(name="booking_number",nullable=false,unique=true,length=30)private String bookingNumber;
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="slot_id")private BookingSlot slot;
 @Column(nullable=false)private int quantity;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private BookingStatus status;
 @Column(name="terms_accepted_at")private Instant termsAcceptedAt;
 @Column(name="terms_snapshot",length=3000)private String termsSnapshot;
 public void acceptTerms(String terms) { if (terms!=null&&!terms.isBlank()) { this.termsSnapshot=terms; this.termsAcceptedAt=Instant.now(); } }
 public Instant getTermsAcceptedAt(){return termsAcceptedAt;}
 @Column(name="confirmed_at",nullable=false)private Instant confirmedAt;@Column(name="cancelled_at")private Instant cancelledAt;@Column(name="checked_in_at")private Instant checkedInAt;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="checked_in_by")private User checkedInBy;@Column(name="checked_out_at")private Instant checkedOutAt;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="checked_out_by")private User checkedOutBy;@Column(name="identity_verified",nullable=false)private boolean identityVerified;@Column(name="verification_note",length=120)private String verificationNote;
 @Column(name="price_base_paise") private Long priceBasePaise;@Column(name="price_subtotal_paise") private Long priceSubtotalPaise;@Column(name="price_tax_paise") private Long priceTaxPaise;@Column(name="price_total_paise") private Long priceTotalPaise;@Column(name="price_rule_id",length=40) private String priceRuleId;@Column(name="tax_rule_id",length=40) private String taxRuleId;@Column(name="price_locked_at") private Instant priceLockedAt;@Column(name="tax_rate_percent",precision=7,scale=3) private java.math.BigDecimal taxRatePercent;@Column(name="tax_inclusive") private Boolean taxInclusive;
 @Column(name="payment_expires_at")private Instant paymentExpiresAt;@Column(name="payment_completed_at")private Instant paymentCompletedAt;@Column(name="status_reason",length=300)private String statusReason;
 @Enumerated(EnumType.STRING)@Column(name="payment_option",length=30)private PaymentOption paymentOption;
 @Enumerated(EnumType.STRING)@Column(name="payment_status",nullable=false,length=30)private BookingPaymentStatus paymentStatus;
 @Enumerated(EnumType.STRING)@Column(name="onsite_payment_method",length=30)private OnsitePaymentMethod onsitePaymentMethod;
 @Column(name="onsite_payment_reference",length=120)private String onsitePaymentReference;@Column(name="onsite_paid_at")private Instant onsitePaidAt;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="onsite_collected_by")private User onsiteCollectedBy;
 protected Booking(){}
 public Booking(User user,BookingSlot slot,int quantity,boolean priced,PaymentOption option,boolean paymentRequired,Instant paymentExpiry){id=UUID.randomUUID();bookingNumber="JNZ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();this.user=user;this.slot=slot;this.quantity=quantity;confirmedAt=Instant.now();paymentOption=priced?option:null;paymentStatus=priced?BookingPaymentStatus.UNPAID:BookingPaymentStatus.NOT_REQUIRED;status=paymentRequired?BookingStatus.PENDING_PAYMENT:BookingStatus.CONFIRMED;paymentExpiresAt=paymentRequired?paymentExpiry:null;}
 public void lockPrice(long basePaise,long subtotalPaise,long taxPaise,long totalPaise,String priceRuleId,String taxRuleId){lockPrice(basePaise,subtotalPaise,taxPaise,totalPaise,priceRuleId,taxRuleId,null,null);}
 public void lockPrice(long basePaise,long subtotalPaise,long taxPaise,long totalPaise,String priceRuleId,String taxRuleId,java.math.BigDecimal taxRatePercent,Boolean taxInclusive){if(priceLockedAt!=null)throw new IllegalStateException("Booking price is already locked");if(basePaise<0||subtotalPaise<0||taxPaise<0||totalPaise<0||subtotalPaise+taxPaise!=totalPaise)throw new IllegalArgumentException("Invalid booking price breakdown");this.priceBasePaise=basePaise;this.priceSubtotalPaise=subtotalPaise;this.priceTaxPaise=taxPaise;this.priceTotalPaise=totalPaise;this.priceRuleId=priceRuleId;this.taxRuleId=taxRuleId;this.taxRatePercent=taxRatePercent;this.taxInclusive=taxInclusive;this.priceLockedAt=Instant.now();}
 public Long getPriceBasePaise(){return priceBasePaise;}public Long getPriceSubtotalPaise(){return priceSubtotalPaise;}public Long getPriceTaxPaise(){return priceTaxPaise;}public Long getPriceTotalPaise(){return priceTotalPaise;}public String getPriceRuleId(){return priceRuleId;}public String getTaxRuleId(){return taxRuleId;}public Instant getPriceLockedAt(){return priceLockedAt;}public java.math.BigDecimal getTaxRatePercent(){return taxRatePercent;}public Boolean getTaxInclusive(){return taxInclusive;}
 public void paid(){if(paymentStatus==BookingPaymentStatus.UNPAID&&(status==BookingStatus.PENDING_PAYMENT||status==BookingStatus.CONFIRMED)){status=BookingStatus.CONFIRMED;paymentStatus=BookingPaymentStatus.PAID;paymentCompletedAt=Instant.now();paymentExpiresAt=null;}}
 public void reschedule(BookingSlot newSlot){this.slot=newSlot;this.statusReason="Rescheduled";}
 public void refunded() {
    if (paymentStatus == BookingPaymentStatus.PAID) {
        paymentStatus = BookingPaymentStatus.REFUNDED;
    }
}
 public void collectOnsite(User operator,OnsitePaymentMethod method,String reference){if(status==BookingStatus.CONFIRMED&&paymentStatus==BookingPaymentStatus.UNPAID){paymentStatus=BookingPaymentStatus.PAID;paymentCompletedAt=Instant.now();onsitePaidAt=paymentCompletedAt;onsiteCollectedBy=operator;onsitePaymentMethod=method;onsitePaymentReference=reference==null||reference.isBlank()?null:reference.trim();}}
 public void expirePayment(){if(status==BookingStatus.PENDING_PAYMENT){status=BookingStatus.PAYMENT_EXPIRED;statusReason="Payment window expired";}}
 public void cancel(String reason){status=BookingStatus.CANCELLED;cancelledAt=Instant.now();statusReason=reason;}public void checkIn(User operator,boolean verified,String note){if(checkedInAt==null){checkedInAt=Instant.now();checkedInBy=operator;identityVerified=verified;verificationNote=note==null||note.isBlank()?null:note.trim();}}public void checkOut(User operator){if(checkedOutAt==null){checkedOutAt=Instant.now();checkedOutBy=operator;}}public void undoCheckIn(){checkedInAt=null;checkedInBy=null;checkedOutAt=null;checkedOutBy=null;identityVerified=false;verificationNote=null;}public void noShow(String reason){if(status==BookingStatus.CONFIRMED){status=BookingStatus.NO_SHOW;statusReason=reason;}}
 public UUID getId(){return id;}public String getBookingNumber(){return bookingNumber;}public User getUser(){return user;}public BookingSlot getSlot(){return slot;}public int getQuantity(){return quantity;}public BookingStatus getStatus(){return status;}public Instant getConfirmedAt(){return confirmedAt;}public Instant getCancelledAt(){return cancelledAt;}public Instant getCheckedInAt(){return checkedInAt;}public User getCheckedInBy(){return checkedInBy;}public Instant getCheckedOutAt(){return checkedOutAt;}public User getCheckedOutBy(){return checkedOutBy;}public boolean isIdentityVerified(){return identityVerified;}public String getVerificationNote(){return verificationNote;}public Instant getPaymentExpiresAt(){return paymentExpiresAt;}public Instant getPaymentCompletedAt(){return paymentCompletedAt;}public String getStatusReason(){return statusReason;}public PaymentOption getPaymentOption(){return paymentOption;}public BookingPaymentStatus getPaymentStatus(){return paymentStatus;}public OnsitePaymentMethod getOnsitePaymentMethod(){return onsitePaymentMethod;}public String getOnsitePaymentReference(){return onsitePaymentReference;}public Instant getOnsitePaidAt(){return onsitePaidAt;}public User getOnsiteCollectedBy(){return onsiteCollectedBy;}
}